1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { StylistView, type StylistStatus } from "./stylist-view";
6	import {
7	  generate,
8	  saveLocation,
9	  predictDefaultOccasion,
10	  logOccasionOverride,
11	} from "@/app/generate/actions";
12	import { defaultReason } from "@/lib/outfits/predict-occasion";
13	import { searchCities, type City } from "@/lib/weather/geocode";
14	import { getCurrentPosition, permissionState, GeoError } from "@/lib/weather/geolocate";
15	import type { LocationSource } from "@/lib/weather/location";
16	import type { GenerateResult, Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
17	
18	type Chosen = { lat: number; lon: number; label: string; source: LocationSource };
19	
20	const DENIED_COPY = "Location access is off — search for a city instead.";
21	const FAILED_COPY = "Couldn't get your location — search for a city instead.";
22	
23	export function Stylist() {
24	  const router = useRouter();
25	  const [status, setStatus] = useState<StylistStatus>("loading");
26	  const [occasion, setOccasion] = useState<UiOccasion>("everyday");
27	  const [formality, setFormality] = useState<number | null>(null);
28	  const [lean, setLean] = useState<string[]>([]);
29	  const [city, setCity] = useState<Chosen | null>(null);
30	  const [nonce, setNonce] = useState(0);
31	  const [reason, setReason] = useState<string>("");
32	  const [seeded, setSeeded] = useState(false);
33	  const predictedRef = useRef<UiOccasion>("everyday");
34	
35	  const [weather, setWeather] = useState<WeatherPayload | null>(null);
36	  const [looks, setLooks] = useState<Look[]>([]);
37	  const [selectedLook, setSelectedLook] = useState(0);
38	  const [cities, setCities] = useState<City[]>([]);
39	  const [refineOpen, setRefineOpen] = useState(false);
40	  const [missing, setMissing] = useState<string | null>(null);
41	  const [locating, setLocating] = useState(false);
42	  const [geoError, setGeoError] = useState<string | null>(null);
43	  // Optimistic: the row shows until we learn the browser has no geolocation at
44	  // all, at which point it disappears and city search is the only path.
45	  const [geoSupported, setGeoSupported] = useState(true);
46	
47	  // The silent refresh must never overwrite a location the user meant to keep.
48	  // Two ways that can happen, both guarded here:
49	  //   1. a RACE — the async permission→position chain resolving after the user
50	  //      has already picked a city in this session;
51	  //   2. a SAVED CITY — profiles.location_source === 'city' is a deliberate
52	  //      choice (decision L2), so GPS must not silently replace it.
53	  // The fix is parked in a ref until both gates are known, so geolocation still
54	  // starts immediately rather than waiting on the first generate to return.
55	  const userChoseRef = useRef(false);
56	  const pendingGeoRef = useRef<Chosen | null>(null);
57	  const geoAllowedRef = useRef<boolean | null>(null); // null = stored origin unknown yet
58	
59	  const applyPendingGeo = useCallback(() => {
60	    if (userChoseRef.current) return; // gate 1
61	    if (geoAllowedRef.current !== true) return; // gate 2
62	    const fix = pendingGeoRef.current;
63	    if (!fix) return;
64	    pendingGeoRef.current = null;
65	    setCity(fix);
66	  }, []);
67	
68	  useEffect(() => {
69	    let cancelled = false;
70	    permissionState().then((state) => {
71	      if (cancelled) return;
72	      if (state === "unsupported") {
73	        setGeoSupported(false);
74	        return;
75	      }
76	      if (state !== "granted") return; // querying never prompts; reading would
77	      getCurrentPosition()
78	        .then((c) => {
79	          if (cancelled) return;
80	          pendingGeoRef.current = { ...c, label: "Current location", source: "geo" };
81	          applyPendingGeo();
82	        })
83	        .catch(() => {
84	          /* silent path — never surface an error the user didn't ask for */
85	        });
86	    });
87	    return () => {
88	      cancelled = true;
89	    };
90	  }, [applyPendingGeo]);
91	
92	  // An explicit tap always wins, including over a saved city.
93	  const useMyLocation = useCallback(() => {
94	    userChoseRef.current = true;
95	    pendingGeoRef.current = null;
96	    setLocating(true);
97	    setGeoError(null);
98	    getCurrentPosition()
99	      .then((c) => setCity({ ...c, label: "Current location", source: "geo" }))
100	      .catch((e) =>
101	        setGeoError(e instanceof GeoError && e.kind === "denied" ? DENIED_COPY : FAILED_COPY),
102	      )
103	      .finally(() => setLocating(false));
104	  }, []);
105	
106	  const applyResult = useCallback(
107	    (res: GenerateResult) => {
108	      // The first result tells us the STORED provenance. A saved city blocks the
109	      // silent refresh for good; anything else releases the parked GPS fix.
110	      if (geoAllowedRef.current === null && res.status !== "error") {
111	        geoAllowedRef.current = res.weather.locationOrigin !== "city";
112	        applyPendingGeo();
113	      }
114	
115	      if (res.status === "ok") {
116	        setWeather(res.weather);
117	        setLooks(res.looks);
118	        setSelectedLook(0);
119	        setStatus("ok");
120	      } else if (res.status === "empty") {
121	        setWeather(res.weather);
122	        setLooks([]);
123	        setMissing(res.missing);
124	        setStatus("empty");
125	      } else {
126	        setStatus("error");
127	      }
128	
129	      // Persist only a location the user actually supplied — including the
130	      // silent refresh, which is the point of keeping the record fresh. Never
131	      // for the profile/default fallback: there is nothing new to write.
132	      if (city && res.status !== "error") {
133	        saveLocation({ ...city, timezone: res.weather.timezone }).catch(() => {
134	          /* non-fatal — never disturb the looks */
135	        });
136	      }
137	    },
138	    [city, applyPendingGeo],
139	  );
140	
141	  // Reads today's stored set (Decision 5). Switching occasion runs this again,
142	  // but the action answers from the database — no AI call, no spend.
143	  // The morning seed: predict the occasion BEFORE the first generate, so the
144	  // generate effect reads the right stored set and runs ONCE. Predicting is
145	  // cheap (no AI/weather). The generate effect is gated on `seeded` below, so
146	  // it never fires for the placeholder "everyday" and then again for the
147	  // prediction — that would spend two AI calls on a fresh day.
148	  useEffect(() => {
149	    let cancelled = false;
150	    predictDefaultOccasion()
151	      .then(({ occasion: predicted, reason: why }) => {
152	        if (cancelled) return;
153	        predictedRef.current = predicted;
154	        setReason(why);
155	        setOccasion(predicted);
156	      })
157	      .finally(() => {
158	        // Release the gate even if prediction fails — looks still load against
159	        // the "everyday" fallback.
160	        if (!cancelled) setSeeded(true);
161	      });
162	    return () => {
163	      cancelled = true;
164	    };
165	  }, []);
166	
167	  useEffect(() => {
168	    if (!seeded) return; // wait for the prediction, so generate runs once
169	    let cancelled = false;
170	    setStatus("loading");
171	    generate({ occasion, formality, lean, city: city ?? undefined }).then((res) => {
172	      if (cancelled) return;
173	      applyResult(res);
174	    });
175	    return () => {
176	      cancelled = true;
177	    };
178	  }, [seeded, occasion, formality, lean, city, nonce, applyResult]);
179	
180	  /**
181	   * The only path that spends an AI call on a day already answered.
182	   *
183	   * Deliberately a direct call rather than an effect dependency: a flag routed
184	   * through the effect can still be in flight when the user switches occasion,
185	   * and would then regenerate that occasion too.
186	   */
187	  const regenerate = useCallback(() => {
188	    setStatus("loading");
189	    generate({ occasion, formality, lean, city: city ?? undefined, regenerate: true }).then(
190	      applyResult,
191	    );
192	  }, [occasion, formality, lean, city, applyResult]);
193	
194	  return (
195	    <StylistView
196	      status={status}
197	      weather={weather}
198	      looks={looks}
199	      selectedLook={selectedLook}
200	      occasion={occasion}
201	      cities={cities}
202	      refineOpen={refineOpen}
203	      missing={missing}
204	      locating={locating}
205	      geoError={geoError}
206	      reason={reason}
207	      onOccasion={(o) => {
208	        setOccasion(o);
209	        setReason(defaultReason(o));
210	        // A tap that departs from the prediction is the flywheel signal for the
211	        // future learner. Fire-and-forget — it must never disturb the looks.
212	        if (o !== predictedRef.current) {
213	          logOccasionOverride({ predicted: predictedRef.current, chosen: o }).catch(() => {});
214	        }
215	      }}
216	      onOpenRefine={() => setRefineOpen(true)}
217	      onCloseRefine={() => setRefineOpen(false)}
218	      onRefineApply={({ formality: f, lean: c }) => {
219	        setFormality(f);
220	        setLean(c);
221	        setRefineOpen(false);
222	      }}
223	      onCityChange={(c) => {
224	        userChoseRef.current = true;
225	        pendingGeoRef.current = null;
226	        setCity({ lat: c.lat, lon: c.lon, label: c.name, source: "city" });
227	      }}
228	      onCitySearch={(q) => {
229	        if (q.trim().length < 2) return;
230	        searchCities(q).then(setCities);
231	      }}
232	      onUseMyLocation={geoSupported ? useMyLocation : undefined}
233	      onSelectLook={setSelectedLook}
234	      onRetry={() => setNonce((n) => n + 1)}
235	      onRegenerate={regenerate}
236	      onOpenItem={(id) => router.push(`/closet/${id}`)}
237	    />
238	  );
239	}
